import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import '../styles/home-page.css';
import image1 from '../images/image1.jpg';
import axios from 'axios';

const HomePage = () => {
  const [expensesCategories, setExpensesCategories] = useState([]); // State to store fetched categories

  const fetchExpensesCategories = async () => {
    try {
      const result = await axios.post(`http://localhost:5001/api/finances/return-categories`);
      setExpensesCategories(result.data); // Update the state with fetched categories
    } catch (error) {
      console.error("Error fetching expense categories:", error);
    }
  };

  // Fetch categories on component mount
  useEffect(() => {
    fetchExpensesCategories();
  }, []);

  return (
    <div className="main-content">
      <div className="home-container">
        <div className="left-content">
          <h1 className="welcome-title">Welcome Kerim</h1>
          <p className="welcome-text">
            Welcome to your Smart Personal Finance Manager. Here you can manage your finances easily and effectively.
          </p>
        </div>

        <div className="image-container">
          <img src={image1} alt="Finance Image" />
        </div>
      </div>

      <div className="expenses-container">
        <div className="expenses-buttons">
          <button className="expense-button">Add Expense</button>
          <button className="expense-button">Exchange</button>
        </div>

        <h2 className="expenses-title">Monthly Expenses</h2>

        <div className="expenses-list">
          {/* Dynamically render fetched categories */}
          {expensesCategories.map((category, index) => (
            <Link
              to={`/${category.name.toLowerCase().replace(/\s+/g, '-')}`} // Generate URL-friendly names
              className="expense-item-link"
              key={index}
            >
              <div className="expense-item">
                <span className="expense-name">{category.name}:</span>
                <span className="expense-amount">{category.amount}KM</span>
              </div>
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
};

export default HomePage;
